import { readFile, writeFile } from "node:fs/promises";
const source = await readFile(
  new URL("../../../src/client-sessions.ts", import.meta.url),
  "utf8",
);
const upsert = source.match(/const UPSERT_KEYS = (\[[^;]+);/)[1];
const restricted = source.match(
  /for \(const key of (\[[^\]]+\])\) if \(body.method === "configure"/,
)[1];
const output = new URL("../src/access-policy.ts", import.meta.url);
const generated =
  "// Generated by scripts/reuse-access-policy.mjs from src/client-sessions.ts. Do not edit.\n" +
  `const UPSERT_KEYS = ${upsert};\nexport const TENANT_CONFIGURATION_KEYS = ${restricted};\n`;
if (process.argv.includes("--check")) {
  if ((await readFile(output, "utf8")) !== generated)
    throw new Error("Workers access policy drifted from src");
} else await writeFile(output, generated);
